g0=[[0]*19 for _ in range(19)]
objects=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
for r,c in [(2,6),(3,5),(3,7),(4,6),(3,13),(4,12),(4,14),(5,13),(9,8),(10,7),(10,9),(11,8),(11,14),(12,13),(12,15),(13,14),(13,3),(14,2),(14,4),(15,3)]:g0[r][c]=3
for r,c,v in objects:g0[r][c]=v
arms={(r+dr,c+dc) for r,c,v in objects for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)]}
blank=(10,8)
out=[row[:] for row in g0]
# horizontal colored rays
for r,c,v in objects:
 for dr,dc in [(0,1),(0,-1)]:
  for step in range(1,19):
   rr,cc=r+dr*step,c+dc*step
   if not(0<=rr<19 and 0<=cc<19): break
   if g0[rr][cc]==3:
    if step==1 and (rr,cc) in arms: continue
    break
   out[rr][cc]=v
# blank cross zero rays, preserving 3s; zero full row/col
br,bc=blank
for j in range(19):
 if g0[br][j]!=3:out[br][j]=0
for i in range(19):
 if g0[i][bc]!=3:out[i][bc]=0
# colored vertical rays
for r,c,v in objects:
 for dr,dc in [(1,0),(-1,0)]:
  for step in range(1,19):
   rr,cc=r+dr*step,c+dc*step
   if not(0<=rr<19 and 0<=cc<19): break
   if g0[rr][cc]==3:
    if step==1 and (rr,cc) in arms: continue
    break
   out[rr][cc]=v
print('\n'.join(' '.join(map(str,row)) for row in out))
